package com.baseer.freshchat;
import java.io.*;
import java.nio.file.*;
import java.util.*;

/** Fresh reconstruction tests: valid state and ordinary disposable fixture I/O only. */
public final class EditorStateTest {
    static final String CO="demo-nour", CV=CO+"-ops";
    static final List<ChatStore.Attachment> NONE=Collections.emptyList();
    static int tests;
    interface Check {void run()throws Exception;}
    static void test(String name,Check check)throws Exception{check.run();tests++;System.out.println("PASS "+name);}
    static void require(boolean value,String why){if(!value)throw new AssertionError(why);}
    static ChatStore.Attachment file(Path directory,String name)throws Exception{Path path=directory.resolve(name);Files.write(path,new byte[10]);return new ChatStore.Attachment(path.toFile().getCanonicalPath(),name,"text/plain",10);}
    static EditorState editor(){return new EditorState(CO,CV,null,"",NONE,null);}
    static ChatStore.Attachment file(String name){return new ChatStore.Attachment("/tmp/synthetic-editor/"+name,name,"text/plain",10);}
    public static void main(String[] args)throws Exception{
        test("unchanged editor starts durably clean",()->{EditorState state=editor();require(!state.dirty(),"clean");require(!state.update("",NONE,null),"no new revision");});
        test("editor lists are isolated from caller and snapshot mutation",()->{ArrayList<ChatStore.Attachment> files=new ArrayList<>();files.add(file("one"));EditorState state=new EditorState(CO,CV,null,"x",files,null);files.clear();EditorState.Snapshot copy=state.snapshot();copy.files.clear();require(state.snapshot().files.size()==1,"isolated lists");});
        test("older acknowledgement cannot acknowledge newer typing",()->{EditorState state=editor();state.update("first",NONE,null);EditorState.Snapshot first=state.snapshot();state.update("second",NONE,null);state.committed(first);require(state.dirty()&&state.snapshot().text.equals("second"),"new typing retained");state.committed(state.snapshot());require(!state.dirty(),"latest acknowledged");});
        test("stale failure cannot replace newer success",()->{EditorState state=editor();state.update("first",NONE,null);EditorState.Snapshot first=state.snapshot();state.update("second",NONE,null);state.committed(state.snapshot());state.failed(first,new IOException("old"));require(state.failure()==null&&!state.dirty(),"late failure ignored");});
        test("failed save retains removed files and reply choice",()->{ChatStore.Attachment a=file("a"),b=file("b");EditorState state=new EditorState(CO,CV,null,"old",Arrays.asList(a,b),"reply");state.update("latest",Collections.singletonList(b),null);state.failed(state.snapshot(),new IOException("full"));require(state.dirty()&&state.failure()!=null&&state.snapshot().text.equals("latest")&&state.snapshot().files.get(0).id.equals(b.id)&&state.snapshot().replyId==null,"intended editor retained");});
        test("serialization retains identity and complete editor without durable acknowledgement",()->{EditorState state=editor();state.update("العربية 🙂",Collections.singletonList(file("copy")),"reply");EditorState.Snapshot saved=roundTrip(state.snapshot());EditorState recovered=EditorState.recover(saved);require(recovered.dirty()&&saved.editorId.equals(recovered.snapshot().editorId)&&saved.text.equals(recovered.snapshot().text)&&saved.files.get(0).id.equals(recovered.snapshot().files.get(0).id),"complete recovery");});
        test("pending send locks edits and retains one token",()->{EditorState state=editor();state.update("send",NONE,null);String token=UUID.randomUUID().toString();EditorState.Snapshot first=state.beginSend(token,CO,CV);require(!state.update("later",NONE,null),"locked");require(state.beginSend(UUID.randomUUID().toString(),CO,CV).sendToken.equals(token),"same token");require(roundTrip(first).sendToken.equals(token),"token serialized");});
        test("ordinary failed send unlocks retained contents",()->{EditorState state=editor();state.update("send",NONE,null);EditorState.Snapshot send=state.beginSend(UUID.randomUUID().toString(),CO,CV);state.sendFailed(send,new IOException("prepublication"));state.sent(send);require(!state.sending()&&state.dirty()&&state.snapshot().text.equals("send"),"stale success rejected");});
        test("uncertain commit retains original token and locks another send",()->{EditorState state=editor();state.update("uncertain",NONE,null);EditorState.Snapshot send=state.beginSend(UUID.randomUUID().toString(),CO,CV);state.commitUncertain(send,new IOException("publication outcome unknown"));require(state.sending()&&send.sendToken.equals(state.snapshot().sendToken)&&state.failure()!=null&&!state.update("overwrite",NONE,null),"pending identity retained");});
        test("successful send clears only its editor and invalidates old save",()->{EditorState state=editor();state.update("send",Collections.singletonList(file("a")),"reply");EditorState.Snapshot old=state.snapshot(),send=state.beginSend(UUID.randomUUID().toString(),CO,CV);state.sent(send);require(!state.dirty()&&!state.sending()&&state.snapshot().text.isEmpty()&&state.snapshot().files.isEmpty()&&state.snapshot().replyId==null&&!state.needsWrite(old),"sent data cannot resurrect");state.update("new",NONE,null);state.sent(send);require(state.snapshot().text.equals("new"),"late completion cannot clear next draft");});
        test("share completion retires preview",()->{EditorState state=new EditorState(null,null,UUID.randomUUID().toString(),"share",NONE,null);EditorState.Snapshot send=state.beginSend(UUID.randomUUID().toString(),CO,CV);state.sent(send);require(state.retired()&&!state.dirty()&&!state.update("again",NONE,null),"retired");});
        test("wrong editor and null-token completions are ignored",()->{EditorState first=editor(),second=editor();first.update("one",NONE,null);second.update("two",NONE,null);first.committed(second.snapshot());first.sent(first.snapshot());require(first.dirty()&&first.snapshot().text.equals("one"),"foreign and null token ignored");});
        test("retired editor cannot accept stale writes",()->{EditorState state=editor();state.update("draft",NONE,null);EditorState.Snapshot snapshot=state.snapshot();state.retire();require(!state.needsWrite(snapshot)&&!state.dirty()&&!state.update("other",NONE,null),"retired cache safe");});
        test("real failed draft write retains editor and retries exactly",EditorStateTest::realDraftFault);
        test("real failed preview write retains exclusions and atomic retry",EditorStateTest::realPreviewFault);
        test("reopen recognizes exactly one committed send UUID",EditorStateTest::realSend);
        System.out.println("PASS: "+tests+" fresh reconstructed editor tests");
    }
    static EditorState.Snapshot roundTrip(EditorState.Snapshot source)throws Exception{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ObjectOutputStream out=new ObjectOutputStream(bytes)){out.writeObject(source);}try(ObjectInputStream in=new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))){return (EditorState.Snapshot)in.readObject();}}
    static void realDraftFault()throws Exception{
        Path directory=Files.createTempDirectory("bchat-editor-reconstructed-");File root=directory.resolve("state.bin").toFile();
        try{ChatStore store=new ChatStore(root);ChatStore.Attachment a=file(directory,"a"),b=file(directory,"b");String reply=store.lastMessage(CO,CV).id;store.setDraft(CO,CV,"prior",Arrays.asList(a,b),reply);byte[] prior=Files.readAllBytes(root.toPath());EditorState state=new EditorState(CO,CV,null,"prior",Arrays.asList(a,b),reply);state.update("latest عربي",Collections.singletonList(b),null);EditorState.Snapshot target=state.snapshot();Path held=directory.resolve("held");Files.move(root.toPath(),held);Files.createDirectory(root.toPath());boolean failed=false;try{store.setDraft(CO,CV,target.text,target.files,target.replyId);}catch(IOException expected){failed=true;state.failed(target,expected);}finally{Files.delete(root.toPath());Files.move(held,root.toPath());}require(failed&&state.dirty()&&state.failure()!=null&&Arrays.equals(prior,Files.readAllBytes(root.toPath())),"real fault retained old root and editor");store.setDraft(CO,CV,target.text,target.files,target.replyId);state.committed(target);ChatStore.Draft saved=new ChatStore(root).draft(CO,CV);require(!state.dirty()&&saved.text.equals(target.text)&&saved.attachments.size()==1&&saved.attachments.get(0).id.equals(b.id)&&saved.replyToMessageId==null,"exact retry");}finally{remove(directory.toFile());}}
    static void realPreviewFault()throws Exception{
        Path directory=Files.createTempDirectory("bchat-preview-reconstructed-");File root=directory.resolve("state.bin").toFile();
        try{ChatStore store=new ChatStore(root);ChatStore.Attachment a=file(directory,"a"),b=file(directory,"b");ChatStore.PendingShare pending=store.stagePendingShare("old",Arrays.asList(a,b));EditorState state=new EditorState(null,null,pending.id,pending.text,pending.attachments,null);state.update("caption",Collections.singletonList(b),null);EditorState.Snapshot target=state.snapshot();Path held=directory.resolve("held");Files.move(root.toPath(),held);Files.createDirectory(root.toPath());boolean failed=false;try{store.updatePendingSharePreview(pending.id,target.text,target.files);}catch(IOException expected){failed=true;state.failed(target,expected);}finally{Files.delete(root.toPath());Files.move(held,root.toPath());}require(failed&&state.snapshot().files.size()==1&&store.pendingShare().attachments.size()==2,"failed preview no rollback of editor");store.updatePendingSharePreview(pending.id,target.text,target.files);state.committed(target);ChatStore.PendingShare saved=new ChatStore(root).pendingShare();require(saved.previewEdited&&saved.text.equals("caption")&&saved.attachments.size()==1&&saved.attachments.get(0).id.equals(b.id),"preview atomic retry");}finally{remove(directory.toFile());}}
    static void realSend()throws Exception{
        Path directory=Files.createTempDirectory("bchat-send-reconstructed-");File root=directory.resolve("state.bin").toFile();
        try{ChatStore store=new ChatStore(root);int count=store.messageCount(CO,CV);EditorState state=editor();state.update("once",NONE,null);EditorState.Snapshot send=state.beginSend(UUID.randomUUID().toString(),CO,CV);store.sendDraftSnapshot(CO,CV,send.text,send.files,send.replyId,send.sendToken);ChatStore reopened=new ChatStore(root);require(reopened.findMessageByClientId(CO,CV,send.sendToken)!=null&&reopened.messageCount(CO,CV)==count+1,"committed UUID discoverable");reopened.sendDraftSnapshot(CO,CV,send.text,send.files,send.replyId,send.sendToken);require(reopened.messageCount(CO,CV)==count+1,"same token idempotent");state.sent(send);require(state.snapshot().text.isEmpty(),"editor acknowledged");}finally{remove(directory.toFile());}}
    static void remove(File path)throws IOException{File[] children=path.listFiles();if(children!=null)for(File child:children)remove(child);Files.deleteIfExists(path.toPath());}
}
